import{_ as i,a0 as l,w as o,s as r,I as n,x as a,a1 as t,A as p,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在系統創建新用户時發送郵件的 Bash 腳本 | LCTT x X-CMD","titleTemplate":false,"description":"在系統創建新用户時發送郵件的 Bash 腳本 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在系統創建新用户時發送郵件的 Bash 腳本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在系統創建新用户時發送郵件的 Bash 腳本 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190801 Bash Script to Send a Mail When a New User Account is Created in System","title":"在系統創建新用户時發送郵件的 Bash 腳本","tag":"201908","desc":""},"relativePath":"201908/20190801 Bash Script to Send a Mail When a New User Account is Created in System.md","filePath":"[post].md"}'),u={name:"201908/20190801 Bash Script to Send a Mail When a New User Account is Created in System.md"};function g(h,s,c,m,k,b){const e=l("Link");return o(),r("div",null,[s[16]||(s[16]=n("h1",{id:"在系統創建新用户時發送郵件的-bash-腳本",tabindex:"-1"},[a("在系統創建新用户時發送郵件的 Bash 腳本 "),n("a",{class:"header-anchor",href:"#在系統創建新用户時發送郵件的-bash-腳本","aria-label":"Permalink to “在系統創建新用户時發送郵件的 Bash 腳本”"},"​")],-1)),s[17]||(s[17]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201908/07/232807l7x4j7y77555j1j5.jpg",alt:""})],-1)),s[18]||(s[18]=n("p",null,"目前市場上有許多開源監測工具可用於監控 Linux 系統的性能。當系統到達指定的閾值時，它將發送郵件提醒。",-1)),s[19]||(s[19]=n("p",null,"它會監控 CPU 利用率、內存利用率、交換內存利用率、磁盤空間利用率等所有內容。但我不認為它們可以選擇監控新用户創建活動，併發送提醒。",-1)),s[20]||(s[20]=n("p",null,"如果沒有，這並不重要，因為我們可以編寫自己的 bash 腳本來實現這一點。",-1)),s[21]||(s[21]=n("p",null,"我們過去寫了許多有用的 shell 腳本。如果要查看它們，請點擊以下鏈接。",-1)),n("ul",null,[n("li",null,[t(e,{href:"https://www.2daygeek.com/category/shell-script/"},{default:p(()=>[...s[0]||(s[0]=[a("如何使用 shell 腳本自動化執行日常任務？",-1)])]),_:1})])]),s[22]||(s[22]=d(`<p>這個腳本做了什麼？它監測 <code>/var/log/secure</code> 文件，並在系統創建新帳户時提醒管理員。</p><p>我們不會經常運行此腳本，因為創建用户不經常發生。但是，我打算一天運行一次這個腳本。因此，我們可以獲得有關用户創建的綜合報告。</p><p>如果在昨天的 <code>/var/log/secure</code> 中找到了 “useradd” 字符串，那麼該腳本將向指定的郵箱發送郵件提醒，其中包含了新用户的詳細信息。</p><p><strong>注意：</strong>你需要更改郵箱而不是使用我們的郵箱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /opt/scripts/new-user.sh</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#Set the variable which equal to zero</span></span>
<span class="line"><span>prev_count=0</span></span>
<span class="line"><span>count=$(grep -i &quot;\`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot; /var/log/secure | egrep -wi &#39;useradd&#39; | wc -l)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ &quot;$prev_count&quot; -lt &quot;$count&quot; ] ; then</span></span>
<span class="line"><span>  # Send a mail to given email id when errors found in log</span></span>
<span class="line"><span>  SUBJECT=&quot;ATTENTION: New User Account is created on server : \`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot;</span></span>
<span class="line"><span>  # This is a temp file, which is created to store the email message.</span></span>
<span class="line"><span>  MESSAGE=&quot;/tmp/new-user-logs.txt&quot;</span></span>
<span class="line"><span>  TO=&quot;2daygeek@gmail.com&quot;</span></span>
<span class="line"><span>  echo  &quot;Hostname: \`hostname\`&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo -e &quot;\\n&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;The New User Details are below.&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  grep -i &quot;\`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot; /var/log/secure | egrep -wi &#39;useradd&#39; | grep -v &#39;failed adding&#39;| awk &#39;{print $4,$8}&#39; | uniq | sed &#39;s/,/ /&#39; &gt;&gt;  $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  mail -s &quot;$SUBJECT&quot; &quot;$TO&quot; &lt; $MESSAGE</span></span>
<span class="line"><span>  rm $MESSAGE</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>給 <code>new-user.sh</code> 添加可執行權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x /opt/scripts/new-user.sh</span></span></code></pre></div><p>最後添加一個 cron 任務來自動化執行它。它會在每天 7 點運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0 7 * * * /bin/bash /opt/scripts/new-user.sh</span></span></code></pre></div><p>注意：你將在每天 7 點收到一封郵件提醒，但這是昨天的日誌。</p><p>你將會看到類似下面的郵件提醒。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /tmp/logs.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hostname: 2g.server10.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The New User Details are below.</span></span>
<span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>2g.server10.com name=magesh</span></span>
<span class="line"><span>2g.server10.com name=daygeek</span></span>
<span class="line"><span>+------------------------------+</span></span></code></pre></div><hr>`,14)),n("p",null,[s[2]||(s[2]=a("via: ",-1)),t(e,{href:"https://www.2daygeek.com/linux-bash-script-to-monitor-user-creation-send-email/"},{default:p(()=>[...s[1]||(s[1]=[a("https://www.2daygeek.com/linux-bash-script-to-monitor-user-creation-send-email/",-1)])]),_:1})]),n("p",null,[s[7]||(s[7]=a("作者：",-1)),t(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[3]||(s[3]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[8]||(s[8]=a(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[4]||(s[4]=[a("lujun9972",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[5]||(s[5]=[a("geekpi",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[6]||(s[6]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:p(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const y=i(u,[["render",g]]);export{w as __pageData,y as default};
